SELECT CASE WHEN budget >= 4228000 THEN 'high' WHEN budget >= 1250000 THEN 'mid' ELSE 'low' END AS budget_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(location))) AS location_values, SUM(budget) AS total_budget, ROUND((100 * SUM(CASE WHEN location = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore FROM departments WHERE dept_name IN ('Finance', 'HR', 'Engineering') OR budget > 2384000 GROUP BY 1;
